// =============================================================================
// File        : tb_systolic_top.v
// Description : System-level self-checking testbench for systolic_top
//               (Phase I design) and for the sequential baseline seq_matmul.
//
//   For every test case in the selected vector file (generated by the Python
//   golden model, model/golden_model.py) the testbench
//     1. writes A and B through the matrix data interface (1 element/cycle),
//     2. pulses start and waits for done,
//     3. reads all N*N results through rd_addr / rd_data (1 element/cycle),
//     4. compares them with the golden-model results.
//
//   It reports the start->done latency and the total host-visible cycles per
//   product (load + compute + read), which is the Phase I baseline for the
//   throughput comparison in the Phase II report.
//
//   Compile-time options
//     +define+DUT_SEQ            test seq_matmul instead of systolic_top
//     +define+RANDOM             use the 1000-test random regression set
// Run  : cd sim && make top | make seq | make regress
// =============================================================================
`timescale 1ns / 1ps

`ifndef VEC_DIR
 `define VEC_DIR "../tests/vectors/"
`endif

`ifdef RANDOM
 `define VEC_FILE "random_vectors.hex"
 `define CNT_FILE "random_count.hex"
`else
 `define VEC_FILE "vectors.hex"
 `define CNT_FILE "vectors_count.hex"
`endif

module tb_systolic_top;

    localparam N         = 4;
    localparam DATA_W    = 8;
    localparam ACC_W     = 32;
    localparam AW        = 4;            // clog2(N*N)
    localparam NN        = N*N;
    localparam MAX_TESTS = 1024;
    localparam WORDS     = MAX_TESTS*3*NN;

    reg                      clk, rst_n, start;
    reg                      wr_en, wr_sel;
    reg  [AW-1:0]            wr_addr, rd_addr;
    reg  [DATA_W-1:0]        wr_data;
    wire                     busy, done;
    wire signed [ACC_W-1:0]  rd_data;

    reg  [31:0] vec [0:WORDS-1];
    reg  [31:0] cnt [0:0];

    integer t, e, num_tests, base;
    integer errors = 0, test_err;
    integer cycles, total_cycles = 0, t_begin;
    integer clk_count = 0;

`ifdef DUT_SEQ
    seq_matmul #(.N(N), .DATA_W(DATA_W), .ACC_W(ACC_W), .AW(AW)) dut (
`else
    systolic_top #(.N(N), .DATA_W(DATA_W), .ACC_W(ACC_W), .AW(AW)) dut (
`endif
        .clk(clk), .rst_n(rst_n),
        .start(start), .busy(busy), .done(done),
        .wr_en(wr_en), .wr_sel(wr_sel), .wr_addr(wr_addr), .wr_data(wr_data),
        .rd_addr(rd_addr), .rd_data(rd_data)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;      // 100 MHz
    always @(posedge clk) clk_count = clk_count + 1;

    // ---------------- interface tasks ----------------
    task write_elem;
        input             sel;
        input [AW-1:0]    addr;
        input [DATA_W-1:0] data;
        begin
            wr_en = 1; wr_sel = sel; wr_addr = addr; wr_data = data;
            @(posedge clk); #1;
            wr_en = 0;
        end
    endtask

    task run_matmul;
        begin
            start = 1; @(posedge clk); #1; start = 0;
            cycles = 1;
            while (!done) begin
                @(posedge clk); #1;
                cycles = cycles + 1;
            end
        end
    endtask

    // ---------------- main sequence ----------------
    initial begin
`ifndef RANDOM
        $dumpfile("tb_systolic_top.vcd");      // no VCD for the long regression
        $dumpvars(0, tb_systolic_top);
`endif

        $readmemh({`VEC_DIR, `CNT_FILE}, cnt);
        num_tests = cnt[0];
        if (num_tests === 32'bx || num_tests == 0) begin
            $display(" RESULT: FAILED - vector files not found in %0s", `VEC_DIR);
            $finish;
        end
        if (num_tests > MAX_TESTS) num_tests = MAX_TESTS;
        $readmemh({`VEC_DIR, `VEC_FILE}, vec, 0, num_tests*3*NN - 1);

        $display("==================================================");
`ifdef DUT_SEQ
        $display(" tb_systolic_top [seq_matmul baseline] : %0d tests", num_tests);
`else
        $display(" tb_systolic_top [systolic_top]        : %0d tests", num_tests);
`endif
        $display("==================================================");

        rst_n = 0; start = 0; wr_en = 0; wr_sel = 0;
        wr_addr = 0; wr_data = 0; rd_addr = 0;
        #22 rst_n = 1;
        @(posedge clk); #1;

        for (t = 0; t < num_tests; t = t + 1) begin
            base     = t*3*NN;
            test_err = 0;
            t_begin  = clk_count;

            // 1. load operands (one element per cycle)
            for (e = 0; e < NN; e = e + 1) write_elem(1'b0, e, vec[base + e][DATA_W-1:0]);
            for (e = 0; e < NN; e = e + 1) write_elem(1'b1, e, vec[base + NN + e][DATA_W-1:0]);

            // 2. compute
            run_matmul;

            // 3. read back (one element per cycle) + 4. compare
            for (e = 0; e < NN; e = e + 1) begin
                rd_addr = e; #1;
                if (rd_data !== $signed(vec[base + 2*NN + e])) begin
                    test_err = test_err + 1;
                    $display("    mismatch test %0d C[%0d][%0d]: got %0d expected %0d",
                             t, e / N, e % N, rd_data, $signed(vec[base + 2*NN + e]));
                end
                @(posedge clk); #1;
            end
            total_cycles = total_cycles + (clk_count - t_begin);

            if (num_tests <= 16) begin
                if (test_err == 0)
                    $display("  [PASS] test %0d : 16/16 elements correct, start->done = %0d cycles",
                             t, cycles);
                else
                    $display("  [FAIL] test %0d : %0d mismatches", t, test_err);
            end
            errors = errors + test_err;
        end

        $display("--------------------------------------------------");
        $display("  start->done latency          : %0d cycles", cycles);
        $display("  host cycles per product      : %0d (load 32 + compute + read 16)",
                 total_cycles / num_tests);
        if (errors == 0) $display(" RESULT: ALL %0d SYSTEM TESTS PASSED", num_tests);
        else             $display(" RESULT: SYSTEM TESTS FAILED (%0d element errors)", errors);
        $display("==================================================");
        #20 $finish;
    end

    // safety timeout
    initial begin
        #20000000;
        $display(" TIMEOUT");
        $finish;
    end

endmodule
